#!/usr/bin/env python3
import json
from pathlib import Path
root=Path('/data/coding/scanweave/qualification/acr06/donorfix'); rows=json.loads((root/'instrumented-traces.json').read_text())
physical={(x['document'],x['id']):x for x in json.loads((root/'physical-measures.json').read_text()) if x['kind']=='retained'}
notes={'w000053s0000':'OCR box spans next o','w000053s0001':'OCR box over-tall and shifted into adjacent ink','w000102s0000':'OCR box spans next o','w000102s0001':'OCR box over-tall and shifted','w000130s0001':'OCR box over-tall','w000175s0001':'OCR box over-tall','w000180s0001':'OCR box extends below observed r','w000471s0000':'OCR box over-tall','w000471s0001':'OCR box over-tall','w000070s0000':'OCR box much larger than target','w000106s0006':'OCR box spans preceding glyphs','w000005s0011':'OCR box over-tall and shifted'}
def fmt(b): return '['+', '.join(f'{x:.1f}' for x in b)+']' if b else 'not measured'
out=['# Issue 29 qualification — in progress','','## Instrumented diagnosis','','Page indexes are zero-based. Instrumented release outputs are byte-identical to main. `instrument.py` generates temporary instrumentation; `trace_instrumented.py` joins it to bounds from the embedded TrueType outline, CID-to-GID mapping and PDF text matrix. Bbox-center displacements are geometric centers, not ink centroids. Bbox intersections are not proof of owned-ink overlap. Full instrumentation and donor cohort records are in `instrumented-traces.json`.','','| Document / page / symbol | OCR box | Observed ink | Retained donor / size | Median L,T,R,B pads | Replacement | Emitted outline bbox | Normalized similarity | Page-scale mask IoU | Neighbor ink pixels | Interpretation |','|---|---|---|---|---|---|---|---|---|---|---|']
for r in rows:
 emitted=r.get('emitted_outline'); phys=physical.get((r['document'],r['id']),{}); iou=phys.get('physical_mask_iou'); overlap=sum(phys.get('separately_owned_neighbor_overlap_pixels',{}).values()); out.append(f"| {r['document']} / {r['page_index']} / {r['id']} ({r['text']}) | {fmt(r['ocr'])} | {fmt(r['ink'])} | {phys.get('witness')} / {phys.get('donor_size')} | {fmt(r['median_pads'])} | {fmt(r['replacement'])} | {fmt(emitted['outline_bbox_px'] if emitted else None)} | {r['similarity']:.3f} | {iou:.3f} | {overlap} | {notes.get(r['id'],'review required')} |")
lines={(x['document'],x['id']):x for x in json.loads((root/'line-metrics.json').read_text())}
out+=['','The next table uses hOCR line estimates. The x-height estimate is `x_size - x_ascenders - x_descenders`; it is not a typographic ground-truth metric. Positive Y is downward. Centroid displacement is from retained donor-mask sampling, while the baseline displacement uses the emitted outline bounding edge.','', '| Document / symbol | Line baseline Y | Estimated x-height | Emitted bottom minus baseline | Emitted top minus x-height line | Donor ink centroid displacement (x,y) |','|---|---|---|---|---|---|']
def number(x): return 'unavailable' if x is None else f'{x:.2f}'
for r in rows:
 l=lines.get((r['document'],r['id']),{}); ph=physical.get((r['document'],r['id']),{}); out.append(f"| {r['document']} / {r['id']} | {number(l.get('estimated_line_baseline_y'))} | {number(l.get('estimated_x_height_px'))} | {number(l.get('emitted_bottom_from_line_baseline'))} | {number(l.get('emitted_top_from_x_height_line'))} | {fmt(ph.get('centroid_displacement'))} |")
out+=['','For single `w000053s0001`, OCR is 17×31 px, observed ink 17×20 px, and the cohort median pads are [1, 1, 1, 0]. Thus inference produces a 15×30 px box: it inherits the tall OCR extent. The financial lowercase `s` donor cohort is labeled `s`, and its witness is 18×26 px; the 14×39 px target OCR box is the cause of the capital-like physical scale. Negative donor pads are dropped by the implementation; the full JSON records discarded counts. The forms examples have discarded negative horizontal pads, while their 47 px OCR heights remain unchanged because their median vertical pads are zero. The recorded cohort labels alone do not prove visual case identity for every donor. Some selected witness IDs differ from the final prototype witness due to subsequent prototype-key reuse; `physical-measures.json` distinguishes the selected and retained witnesses. The candidate gate uses the finally retained donor. Physical mask IoU is computed at page scale with nearest-neighbor mask sampling; it is not a measurement of antialiased PDF pixels.','','## Work in progress','','The final candidate and qualification checks are running. No release conclusion or full results are claimed yet.']
(root/'REPORT.md').write_text('\n'.join(out)+'\n')
